import type { Product } from '../types/product';

/** Retardo por defecto antes de buscar, en milisegundos. */
const DEFAULT_DEBOUNCE_MS = 300;

/** Mínimo de caracteres para lanzar una búsqueda. */
const MIN_QUERY_LENGTH = 2;

/**
 * Activa el buscador con autocompletado dentro de `root`.
 * Lanza `search` tras un retardo sin teclas y muestra solo el resultado de la última búsqueda.
 * @param root Elemento que contiene la estructura `.search-box`.
 * @param search Función que devuelve los productos que coinciden con el texto.
 * @param options Opciones; `debounceMs` define el retardo antes de buscar.
 */
export function initSearchBox(
  root: HTMLElement,
  search: (query: string) => Promise<Product[]>,
  options?: { debounceMs?: number }
): void {
  const debounceMs = options?.debounceMs ?? DEFAULT_DEBOUNCE_MS;
  const input = root.querySelector<HTMLInputElement>('.search-box__input');
  const list = root.querySelector<HTMLUListElement>('.search-box__results');
  const status = root.querySelector<HTMLParagraphElement>('.search-box__status');

  if (!input || !list || !status) {
    throw new Error('initSearchBox: estructura del buscador incompleta');
  }

  input.setAttribute('aria-controls', 'search-results');
  status.setAttribute('aria-live', 'polite');

  let timer: ReturnType<typeof setTimeout> | undefined;
  let latestRequest = 0;

  /** Pinta la lista y el estado; el nombre se asigna como texto literal. */
  const render = (products: Product[], message: string): void => {
    list.textContent = '';
    for (const product of products) {
      const item = document.createElement('li');
      item.className = 'search-box__item';
      const price = (product.priceCents / 100).toFixed(2);
      item.textContent = `${product.name} — $${price}`;
      list.appendChild(item);
    }
    status.textContent = message;
  };

  /** Lanza una búsqueda y pinta su resultado solo si sigue siendo la última. */
  const run = async (query: string): Promise<void> => {
    latestRequest += 1;
    const requestId = latestRequest;
    try {
      const products = await search(query);
      if (requestId !== latestRequest) return;
      render(products, products.length === 0 ? 'Sin resultados' : '');
    } catch {
      if (requestId !== latestRequest) return;
      render([], 'Error al buscar');
    }
  };

  input.addEventListener('input', () => {
    if (timer !== undefined) {
      clearTimeout(timer);
      timer = undefined;
    }
    const query = input.value.trim();
    if (query.length < MIN_QUERY_LENGTH) {
      latestRequest += 1;
      render([], '');
      return;
    }
    timer = setTimeout(() => {
      timer = undefined;
      void run(query);
    }, debounceMs);
  });
}
